"""HTTP response models (versioned; OpenAPI generated by FastAPI)."""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict

from backend.app.domain.instrument import Instrument

HTTP_SCHEMA_VERSION = "1.0"


class HealthResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")

    schema_version: str = HTTP_SCHEMA_VERSION
    status: str  # "ok" | "offline" | "degraded"
    version: str
    network: str  # "online" | "offline" (explicit, never faked)


class InstrumentsResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")

    schema_version: str = HTTP_SCHEMA_VERSION
    instruments: list[Instrument]
